p='web/src/app/api/score/route.ts'
s=open(p,encoding='utf-8').read()
start=s.index("// Looks for an active's name within WINDOW_WORDS")
end=s.index('function scoreRule1(')
new='''// Maps an offset in the normalized window text back to a character span in the
// original ad text, by walking the window's tokens and their normalized lengths.
function mapToChars(
  window: Token[],
  at: number,
  length: number,
): { start: number; end: number } | null {
  let cursor = 0;
  let start: number | null = null;
  let end: number | null = null;
  for (const token of window) {
    const norm = normalize(token.text);
    const tokenStart = cursor;
    const tokenEnd = cursor + norm.length;
    if (tokenEnd > at && start === null) start = token.start;
    if (tokenStart < at + length) end = token.end;
    cursor = tokenEnd + 1; // the space rejoined below
  }
  return start === null || end === null ? null : { start, end };
}

// Looks for an active's name within WINDOW_WORDS either side of a percentage.
// The NEAREST name wins, not the longest: in "Salicylic Acid 2%, Niacinamide
// 10%" the 10% belongs to Niacinamide even though "Salicylic Acid" is a longer
// name still inside the window. Length only breaks ties at equal distance, so
// "Salicylic Acid + LHA 0.2%" resolves to the cleanser and not to bare "LHA".
function nameNearPercent(
  text: string,
  tokens: Token[],
  hit: PercentHit,
  names: string[],
): { name: string; start: number; end: number } | null {
  const hitIndex = tokens.findIndex((t) => t.end > hit.start && t.start < hit.end);
  if (hitIndex === -1) return null;

  const from = Math.max(0, hitIndex - WINDOW_WORDS);
  const to = Math.min(tokens.length - 1, hitIndex + WINDOW_WORDS);
  const window = tokens.slice(from, to + 1);
  const windowText = normalize(window.map((t) => t.text).join(" "));

  let best: { name: string; start: number; end: number } | null = null;
  let bestDistance = Infinity;

  for (const name of names) {
    const needle = normalize(name);
    if (needle.length === 0) continue;

    // Every occurrence, not just the first — the same active can appear twice
    // in one window with only one of them next to this percentage.
    for (let at = windowText.indexOf(needle); at !== -1; at = windowText.indexOf(needle, at + 1)) {
      const chars = mapToChars(window, at, needle.length);
      if (chars === null) continue;

      const distance =
        chars.end <= hit.start
          ? hit.start - chars.end
          : hit.end <= chars.start
            ? chars.start - hit.end
            : 0;

      const closer = distance < bestDistance;
      const tiedButLonger =
        distance === bestDistance && best !== null && needle.length > normalize(best.name).length;
      if (!closer && !tiedButLonger) continue;

      bestDistance = distance;
      best = {
        name,
        start: Math.min(chars.start, hit.start),
        end: Math.max(chars.end, hit.end),
      };
    }
  }

  return best;
}

'''
